finding.falsifier_code:
import bisect, hashlib

def ring_hash(s):
    return int.from_bytes(hashlib.blake2b(s.encode(), digest_size=8).digest(), "big")

class HashRing:
    def __init__(self, members, vnodes):
        self.points = []
        for m in members:
            for j in range(vnodes):
                self.points.append((ring_hash(f"{m}#{j}"), m))
        self.points.sort()
        self.keys = [p[0] for p in self.points]

ring = HashRing(["dist-00", "dist-01"], 1)
exact_key_hash = ring.keys[0]
exact_node = ring.points[0][1]

# Simulate locate() for a key that hashes exactly to exact_key_hash
idx = bisect.bisect_right(ring.keys, exact_key_hash)
routed_node = ring.points[idx % len(ring.points)][1]

if routed_node != exact_node:
    print("FALSIFIED")
    raise AssertionError(f"Defect present: exact hash routed to {routed_node} instead of {exact_node}")

